import{_ as n,o as t,c as o,ai as s}from"./chunks/framework.Ai2o9gNv.js";const a="/assets/image-20250310014455245.CTuNTY4e.png",i="/assets/image-20250310014629433.BxQBRucy.png",p="/assets/image-20250310014723218.B3AeaB_o.png",r="/assets/image-20250310014837997.BtVcu2JQ.png",d="/assets/image-20250310014857033.BIDkQOeU.png",g="/assets/image-20250310015026848.CEhqe-t6.png",l="/assets/image-20250310015150136.DVF0kSuQ.png",c="/assets/image-20250310015404382.qg9nH8IX.png",m="/assets/image-20250310020254575.5ormwTdF.png",u="/assets/image-20250310021016941.DlkxIOL7.png",h="/assets/image-20250310020405900.03bIvrto.png",_="/assets/image-20250310021218929.Dlmj3wSt.png",v="/assets/image-20250310021328772.D3_Wp4nN.png",D="/assets/image-20250310021847340.BfHhjWoq.png",S="/assets/image-20250310022006247.opJotZsy.png",f=JSON.parse('{"title":"喜大普奔 DevEco Studio 官方接 入 DeepSeek 了","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/DevEco Studio 官方接入DeepSeek了/DevEco Studio 官方接入DeepSeek了.md","filePath":"鸿蒙开发技巧/DevEco Studio 官方接入DeepSeek了/DevEco Studio 官方接入DeepSeek了.md","lastUpdated":1741544779000,"__rawMarkdown":"# 喜大普奔 DevEco Studio 官方接 入 DeepSeek 了\\n\\n**喜大普奔**，最新版本 DevEco Studio 的 AI 工具 CodeGenie 接入 DeepSeek，随着各种 AI 工具的快速发展，CodeGenie 的 DeepSeek 接入\\n\\n可谓是姗姗来迟了。\\n\\n## 效果一览\\n\\n先来看一眼接入的效果模样：\\n\\n![image-20250310014455245](assets/image-20250310014455245.png)\\n\\n接下来我们来看一下如何进行接入！\\n\\n## 要求的软件版本\\n\\n1. **DevEco Studio**\\n\\n![image-20250310014629433](assets/image-20250310014629433.png)\\n\\n2. **CodeGenie**\\n\\n   ![image-20250310014723218](assets/image-20250310014723218.png)\\n\\n下载地址都可以在官网中获取\\n\\n1. **DevEco Studio**\\n\\n   ```\\n   https://developer.huawei.com/consumer/cn/download/deveco-studio\\n   ```\\n\\n   ![image-20250310014837997](assets/image-20250310014837997.png)\\n\\n2. **CodeGenie**\\n\\n   ```\\n   https://developer.huawei.com/consumer/cn/download/deveco-codegenie\\n   ```\\n\\n   ![image-20250310014857033](assets/image-20250310014857033.png)\\n\\n## 安装 CodeGenie 步骤\\n\\n1. 下载**CodeGenie** 插件，_不用解压_\\n\\n   ![image-20250310015026848](assets/image-20250310015026848.png)\\n\\n2. **DevEco Studio** 中安装\\n\\n   > 文件->设置->插件->设置->从磁盘安装插件， 然后重启\\n\\n   ![image-20250310015150136](assets/image-20250310015150136.png)\\n\\n## CodeGenie 实用功能\\n\\n**CodeGenie** 目前提供的主要功能有：\\n\\n1. **智能问答 _DeepSeek_**\\n2. **编辑器 AI 代码提示**\\n3. **编译报错智能分析**\\n4. 万能卡片生成\\n\\n### 智能问答 DeepSeek\\n\\n重新打开 **DevEco Studio**后，点击侧边栏的 **CodeGenie**，进行华为账户登录后，便可以实用 **CodeGenie**了，可以在这里调用 DeepSeek。\\n\\n![image-20250310015404382](assets/image-20250310015404382.png)\\n\\n然后就可以进行智能问答了。\\n\\n问：鸿蒙应用开发中，常见的状态装饰器有哪些？\\n\\n答：\\n\\n![image-20250310020254575](assets/image-20250310020254575.png)\\n\\n### 编辑器 AI 代码提示\\n\\n当前的**CodeGenie**也支持编辑器内 AI 代码提示。\\n\\n默认情况下，开发者可以在代码文件的任意位置使用热键 Alt+X 或 Alt+C 手动触发代码生成，也可以在设置中开启 \\"片段生成\\" 或 \\"行内生成\\" 选项，AI 将基于代码上下文自动进行续写。\\n\\n**Alt+X**\\n\\n![image-20250310021016941](assets/image-20250310021016941.png)\\n\\n**代码生成的配置**\\n\\n![image-20250310020405900](assets/image-20250310020405900.png)\\n\\n### 编译报错智能分析\\n\\n开发中，如果程序出现了编译错误，可以快速的调用 AI 能力进行错误分析。\\n\\n示例：将 API 版本由 14 改为 22 _22 是不正确的版本_\\n\\n![image-20250310021218929](assets/image-20250310021218929.png)\\n\\n**执行编译**\\n\\n![image-20250310021328772](assets/image-20250310021328772.png)\\n\\n可以看到，此时 **CodeGenie**边开始思考和分析错误了，然后给出答案\\n\\n![image-20250310021847340](assets/image-20250310021847340.png)\\n\\n### 万能卡片生成\\n\\n万能卡片生成算是**CodeGenie**的常规功能了。\\n\\n![image-20250310022006247](assets/image-20250310022006247.png)\\n\\n切换到万能卡片选项，参考以下提示词，便可以生成万能卡片代码了。\\n\\n| **序号** | **建议描述维度** | **说明**                                                                                                                                                               | **举例**                                                       |\\n| -------- | ---------------- | ---------------------------------------------------------------------------------------------------------------------------------------------------------------------- | -------------------------------------------------------------- |\\n| 1        | 卡片用途         | 卡片的用途/业务场景，比如电商购物、娱乐、生活服务类等。                                                                                                                | 例如“电商购物卡片”、“娱乐类卡片”。                             |\\n| 2        | 卡片功能         | 卡片包含的组件，如图标、标题、按钮等；组件的状态信息，如图标主题、标题内容、按钮显示的文字等。                                                                         | 例如“新品上市主标题”、“商品搜索按钮”、“热门电影子板块入口”等。 |\\n| 3        | 卡片尺寸         | HamonyOS 官网提供的四种卡片尺寸：1*2（微卡片）、2*2（小卡片）、2*4（中卡片）、4*4（大卡片）；卡片尺寸非必选项，AI 会根据前两个维度描述的信息，智能选择效果最佳的尺寸。 | 例如“2\\\\*2 尺寸的卡片”、“中卡片”等                              |\\n\\n## 总结\\n\\n​ 随着 **DeepSeek** 的正式接入，**DevEco Studio** 的 **CodeGenie** 工具实现了从“代码助手”到“开发全流程智能伙伴”的跨越升级。无论是\\n\\n通过 **智能问答** 快速解决技术难题，还是借助 **AI 代码提示** 提升编码效率，甚至是利用 **编译报错分析** 精准定位问题，这一系列功能都\\n\\n显著降低了鸿蒙应用开发的门槛，让开发者更专注于创新与业务逻辑的实现。**万能卡片生成** 等特色功能，进一步展现了 AI 在垂直场\\n\\n景中的实用价值，为鸿蒙生态的多样化开发需求提供了高效解决方案。此次更新不仅是华为在开发者工具领域的一次重要突破，更\\n\\n预示着 AI 与 IDE 深度结合的无限潜力。\\n\\n​ 建议开发者尽快升级至最新版本，体验 **CodeGenie + DeepSeek** 的协同效能，解锁更智能、更流畅的开发体验。未来，随着 AI 技术的持续迭代，相信鸿蒙生态将迎来更强大的开发工具支持，赋能更多创新应用落地。\\n\\n**立即行动**：\\n\\n- 下载 DevEco Studio：[官网链接](https://developer.huawei.com/consumer/cn/download/deveco-studio)\\n- 获取 CodeGenie 插件：[插件地址](https://developer.huawei.com/consumer/cn/download/deveco-codegenie)\\n\\n让 AI 为你的代码插上翅膀，开启高效开发新时代！🚀\\n"}'),k={name:"鸿蒙开发技巧/DevEco Studio 官方接入DeepSeek了/DevEco Studio 官方接入DeepSeek了.md"};function b(C,e,A,I,G,E){return t(),o("div",null,[...e[0]||(e[0]=[s("",55)])])}const w=n(k,[["render",b]]);export{f as __pageData,w as default};
